; DUNGEON.DAT: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; DUNGEON.DAT: the 3D dungeon view, a code overlay EXODUS loads at 0100 (0100-084A).
; 0103-0106 hold what it is given, 0107-0446 are byte tables, the code starts at 0447.
;
; Overview. EXODUS (DUNEVENT 9630) clears the view and, when a light is lit, calls 0100 with
; BX = party x,y, AL = facing (0 north, 1 east, 2 south, 3 west), AH = level. DrawDungeonView
; looks at up to 32 "view slots": cells at fixed offsets around the party (SlotDXTbl/SlotDYTbl,
; written for facing north and rotated by DrawSlot), up to 3 cells ahead and 3 to each side,
; near to far, and draws each cell's wall face, door, ladders and chest. It stops a line of sight
; at the first wall, so nothing hidden is drawn (there is no other clipping).
; Drawing: everything is white (pixel value 3) ORed into CGA memory (ES = B800). The view has its
; own coordinates: x 00-80h, y 00-7Fh, horizon and centre at 40h; screen pixel = view + 20h (the
; 11x11 map window). A wall face is a set of vertical lines every second pixel (stripes, DrawFace);
; a door fills the gaps between the stripes (solid); ladders are lines (DrawLine), a chest a filled
; box (DrawChest). The perspective is not exact: each step away halves the size (front faces
; 80h, 40h, 20h, 10h wide).
; View slots (dx, dy for facing north; F = front face, S = side face of that cell):
;   0 (0,0) own cell, whole view    1 (-1,0) S   2 (1,0) S
;   3 (-1,-1) F  4 (0,-1) F  5 (1,-1) F  6 (-2,-1) S  7 (-1,-1) S  8 (1,-1) S  9 (2,-1) S
;   10-14 (-2..2,-2) F   15 (-3,-2) S  16 (-2,-2) S  17 (-1,-2) S  18 (1,-2) S  19 (2,-2) S  20 (3,-2) S
;   21-27 (-3..3,-3) F   28 (-2,-3) S  29 (-1,-3) S  30 (1,-3) S  31 (2,-3) S
; A cell that is in two slots (3 and 7, ...) gets half of its ladder or chest drawn by each.
; Cell bytes (docs/FORMATS.md 4): >= 80h wall-like: 80-BF a plain wall (so A0, the secret door,
; looks like a wall), C0-FF a wall with a door; below 80h open: bit 10h ladder up, 20h ladder
; down, 40h chest; the low nibble (events) is not drawn.
; Owns: ViewPos/ViewFacing/ViewLevel and the tables. Uses EXODUS's DMAP (the dungeon) and ROWTAB.
DMAP EQU 900h	; an address in the program this file is loaded into
ROWTAB EQU 132Ah	; an address in the program this file is loaded into
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
ORG 100h
	jmp DrawDungeonView	;@0100
ViewPos label byte	; party x (low byte), y (high byte), 0-15
	db 0h,0h	;@0103
ViewFacing label byte	; 0 north, 1 east, 2 south, 3 west
	db 0h	;@0105
ViewLevel label byte	; dungeon level 0-7
	db 0h	;@0106
; SlotDXTbl, SlotDYTbl: the cell offset (dx, dy) of each of the 32 view slots for facing north
; (dy negative = ahead); DrawSlot turns it to the facing. The list is in the module header.
SlotDXTbl label byte
	db 0h,0FFh,1h,0FFh,0h,1h,0FEh,0FFh,1h,2h,0FEh,0FFh,0h,1h,2h,0FDh	;@0107
	db 0FEh,0FFh,1h,2h,3h,0FDh,0FEh,0FFh,0h,1h,2h,3h,0FEh,0FFh,1h,2h	;@0117
SlotDYTbl label byte
	db 0h,0h,0h,0FFh,0FFh,0FFh,0FFh,0FFh,0FFh,0FFh,0FEh,0FEh,0FEh,0FEh,0FEh,0FEh	;@0127
	db 0FEh,0FEh,0FEh,0FEh,0FEh,0FDh,0FDh,0FDh,0FDh,0FDh,0FDh,0FDh,0FDh,0FDh,0FDh,0FDh	;@0137
; LadderTbl: how a ladder in an open cell is drawn, 8 bytes for each of slots 0-20 (no ladders
; farther away), used by DrawLadder: +0 left rail x, +1 right rail x, +2 left rail's top y,
; +3 right rail's top y (0 = this rail not seen), +4 and +5 the two rungs' y. The rails run from
; that y to the horizon (40h), two pixels wide; for a ladder down every y becomes 7Fh - y.
; +6 and +7 (the lower half's rung y, about 7Fh - [+5] and 7Fh - [+4]) are never read.
LadderTbl label byte
	db 30h,50h,10h,10h,20h,34h,4Ch,60h,0h,10h,0h,10h,20h,34h,4Ch,60h	;@0147
	db 70h,80h,10h,0h,20h,34h,4Ch,60h,18h,20h,28h,0h,30h,3Ah,46h,50h	;@0157
	db 38h,48h,28h,28h,30h,3Ah,46h,50h,60h,68h,0h,28h,30h,3Ah,46h,50h	;@0167
	db 0h,8h,0h,28h,30h,3Ah,46h,50h,20h,28h,0h,28h,30h,3Ah,46h,50h	;@0177
	db 58h,60h,28h,0h,30h,3Ah,46h,50h,78h,80h,28h,0h,30h,3Ah,46h,50h	;@0187
	db 1Ch,20h,34h,0h,38h,3Dh,42h,48h,2Ch,30h,34h,0h,38h,3Dh,42h,48h	;@0197
	db 3Ch,44h,34h,34h,38h,3Dh,42h,48h,50h,54h,0h,34h,38h,3Dh,42h,48h	;@01A7
	db 60h,64h,0h,34h,38h,3Dh,42h,48h,0h,4h,0h,34h,38h,3Dh,42h,48h	;@01B7
	db 20h,24h,0h,34h,38h,3Dh,42h,48h,30h,34h,0h,34h,38h,3Dh,42h,48h	;@01C7
	db 4Ch,50h,34h,0h,38h,3Dh,42h,48h,5Ch,60h,34h,0h,38h,3Dh,42h,48h	;@01D7
	db 7Ch,80h,34h,0h,38h,3Dh,42h,48h,0FFh,0h,0h,0h	; 01EF-01F2 unused (slot 21?)	;@01E7
; ChestTbl: the box drawn for a chest (cell bit 40h), 4 bytes for each of slots 0-20, used by
; DrawChest: +0 left x, +1 right x (excluded), +2 top y, +3 bottom y (excluded).
ChestTbl label byte
	db 30h,50h,68h,78h,0h,10h,68h,78h,70h,80h,68h,78h,18h,20h,54h,5Ch	;@01F3
	db 38h,48h,54h,5Ch,60h,68h,54h,5Ch,0h,8h,54h,5Ch,20h,28h,54h,5Ch	;@0203
	db 58h,60h,54h,5Ch,78h,80h,54h,5Ch,1Ch,20h,4Ah,4Eh,2Ch,30h,4Ah,4Eh	;@0213
	db 3Ch,44h,4Ah,4Eh,50h,54h,4Ah,4Eh,60h,64h,4Ah,4Eh,0Ch,14h,4Ah,4Eh	;@0223
	db 20h,24h,4Ah,4Eh,30h,34h,4Ah,4Eh,4Ch,50h,4Ah,4Eh,5Ch,60h,4Ah,4Eh	;@0233
	db 6Ch,74h,4Ah,4Eh	;@0243
; FaceTbl: 64 entries of 8 bytes, used by DrawFace: 0-31 the wall face of view slot 0-31, 32-63
; the door of slot 0-31 (drawn over the wall for cells C0-FF; 32, the door around you when you
; stand in one, is erased instead). +0 x of the first line, +1 its top y, +2 its bottom y
; (excluded), +3 x step (2 = rightwards, FE = leftwards), +4 the top moves down a pixel every
; [+4] pixels across, +5 the bottom moves up a pixel every [+5] pixels (FF = never, a front face),
; +6 number of lines, +7 unused (0).
FaceTbl label byte
	db 0h,0h,80h,2h,0FFh,0FFh,41h,0h,1h,0h,80h,2h,1h,1h,10h,0h	;@0247
	db 7Fh,0h,80h,0FEh,1h,1h,10h,0h,0h,20h,60h,2h,0FFh,0FFh,10h,0h	;@0257
	db 20h,20h,60h,2h,0FFh,0FFh,21h,0h,80h,20h,60h,0FEh,0FFh,0FFh,10h,0h	;@0267
	db 1h,20h,60h,2h,2h,2h,10h,0h,21h,20h,60h,2h,1h,1h,8h,0h	;@0277
	db 5Fh,20h,60h,0FEh,1h,1h,8h,0h,7Fh,20h,60h,0FEh,2h,2h,10h,0h	;@0287
	db 0h,30h,50h,2h,0FFh,0FFh,10h,0h,20h,30h,50h,2h,0FFh,0FFh,8h,0h	;@0297
	db 30h,30h,50h,2h,0FFh,0FFh,11h,0h,60h,30h,50h,0FEh,0FFh,0FFh,8h,0h	;@02A7
	db 80h,30h,50h,0FEh,0FFh,0FFh,10h,0h,1h,30h,50h,2h,4h,4h,10h,0h	;@02B7
	db 21h,30h,50h,2h,2h,2h,8h,0h,31h,30h,50h,2h,1h,1h,4h,0h	;@02C7
	db 4Fh,30h,50h,0FEh,1h,1h,4h,0h,5Fh,30h,50h,0FEh,2h,2h,8h,0h	;@02D7
	db 7Fh,30h,50h,0FEh,4h,4h,10h,0h,0h,38h,48h,2h,0FFh,0FFh,10h,0h	;@02E7
	db 20h,38h,48h,2h,0FFh,0FFh,8h,0h,30h,38h,48h,2h,0FFh,0FFh,4h,0h	;@02F7
	db 38h,38h,48h,2h,0FFh,0FFh,9h,0h,50h,38h,48h,0FEh,0FFh,0FFh,4h,0h	;@0307
	db 60h,38h,48h,0FEh,0FFh,0FFh,8h,0h,80h,38h,48h,0FEh,0FFh,0FFh,10h,0h	;@0317
	db 31h,38h,48h,2h,2h,2h,4h,0h,39h,38h,48h,2h,1h,1h,4h,0h	;@0327
	db 47h,38h,48h,0FEh,1h,1h,4h,0h,4Fh,38h,48h,0FEh,2h,2h,4h,0h	;@0337
	db 20h,20h,80h,2h,0FFh,0FFh,21h,0h,2h,20h,80h,2h,2h,1h,8h,0h	;@0347
	db 7Eh,20h,80h,0FEh,2h,1h,8h,0h,1h,30h,60h,2h,0FFh,0FFh,8h,0h	;@0357
	db 31h,30h,60h,2h,0FFh,0FFh,10h,0h,7Fh,30h,60h,0FEh,0FFh,0FFh,8h,0h	;@0367
	db 0Ch,2Eh,5Bh,2h,4h,2h,6h,0h,26h,2Eh,5Bh,2h,2h,1h,3h,0h	;@0377
	db 5Ah,2Eh,5Bh,0FEh,2h,1h,3h,0h,74h,2Eh,5Bh,0FEh,4h,2h,6h,0h	;@0387
	db 11h,38h,50h,2h,0FFh,0FFh,5h,0h,23h,38h,50h,2h,0FFh,0FFh,5h,0h	;@0397
	db 3Bh,38h,50h,2h,0FFh,0FFh,6h,0h,5Dh,38h,50h,0FEh,0FFh,0FFh,5h,0h	;@03A7
	db 6Fh,38h,50h,0FEh,0FFh,0FFh,5h,0h,0Eh,36h,4Dh,2h,8h,4h,4h,0h	;@03B7
	db 26h,36h,4Dh,2h,4h,2h,2h,0h,34h,36h,4Dh,2h,2h,1h,1h,0h	;@03C7
	db 4Ch,36h,4Dh,0FEh,2h,1h,1h,0h,5Ah,36h,4Dh,0FEh,4h,2h,2h,0h	;@03D7
	db 72h,36h,4Dh,0FEh,8h,4h,4h,0h,11h,3Ch,48h,2h,0FFh,0FFh,3h,0h	;@03E7
	db 25h,3Ch,48h,2h,0FFh,0FFh,3h,0h,33h,3Ch,48h,2h,0FFh,0FFh,3h,0h	;@03F7
	db 3Dh,3Ch,48h,2h,0FFh,0FFh,4h,0h,4Dh,3Ch,48h,0FEh,0FFh,0FFh,3h,0h	;@0407
	db 5Bh,3Ch,48h,0FEh,0FFh,0FFh,3h,0h,7Fh,3Ch,48h,0FEh,0FFh,0FFh,3h,0h	;@0417
	db 34h,3Fh,46h,2h,1h,2h,1h,0h,3Ch,3Fh,46h,2h,1h,1h,1h,0h	;@0427
	db 44h,3Fh,46h,0FEh,1h,1h,1h,0h,4Ch,3Fh,46h,0FEh,1h,2h,1h,0h	;@0437
;------------------------------------------------------------------------------
; DrawDungeonView: the entry (0100 jumps here). Draw the 3D view from the party's cell into the
; (already cleared) screen. Slot by slot, near to far: each line of sight (to the left, to the
; right, then the cells ahead and the lines of sight beside them) ends at the first wall.
; In: BX = x (BL), y (BH); AL = facing 0-3; AH = level 0-7. Out: the view drawn.
; Saves all registers and the flags.
;------------------------------------------------------------------------------
DrawDungeonView:	pushf	;@0447
	push ax	;@0448
	push es	;@0449
	mov word ptr ViewPos, bx	;@044A
	mov byte ptr ViewFacing, al	;@044E
	mov byte ptr ViewLevel, ah	;@0451
	mov ax, 0B800h	;@0455
	mov es, ax	;@0458
	mov al, 0	; own cell	;@045A
	call DrawSlot	;@045C
	je DrawView_Left0	; open: look around	;@045F
	jns DrawView_Ahead1	; standing in a door: only straight ahead	;@0461
	jmp DrawView_Done	; in a wall (or secret door): nothing more	;@0463
; to the left: the wall beside you, then the cells diagonally to the left
DrawView_Left0:	mov al, 1	;@0466
	call DrawSlot	;@0468
	js DrawView_Right0	;@046B
	mov al, 3	;@046D
	call DrawSlot	;@046F
	js DrawView_Right0	;@0472
	mov al, 6	;@0474
	call DrawSlot	;@0476
	js DrawView_Right0	;@0479
	mov al, 0Ah	;@047B
	call DrawSlot	;@047D
	js DrawView_Right0	;@0480
	mov al, 0Fh	;@0482
	call DrawSlot	;@0484
	js DrawView_Right0	;@0487
	mov al, 15h	;@0489
	call DrawSlot	;@048B
; to the right, the same
DrawView_Right0:	mov al, 2	;@048E
	call DrawSlot	;@0490
	js DrawView_Ahead1	;@0493
	mov al, 5	;@0495
	call DrawSlot	;@0497
	js DrawView_Ahead1	;@049A
	mov al, 9	;@049C
	call DrawSlot	;@049E
	js DrawView_Ahead1	;@04A1
	mov al, 0Eh	;@04A3
	call DrawSlot	;@04A5
	js DrawView_Ahead1	;@04A8
	mov al, 14h	;@04AA
	call DrawSlot	;@04AC
	js DrawView_Ahead1	;@04AF
	mov al, 1Bh	;@04B1
	call DrawSlot	;@04B3
; one cell ahead; if it is open, the lines of sight to its left and right
DrawView_Ahead1:	mov al, 4	;@04B6
	call DrawSlot	;@04B8
	jne DrawView_Done	; a wall or door ahead ends the view	;@04BB
	mov al, 7	;@04BD
	call DrawSlot	;@04BF
	js DrawView_Right1	;@04C2
	mov al, 0Bh	;@04C4
	call DrawSlot	;@04C6
	js DrawView_Right1	;@04C9
	mov al, 10h	;@04CB
	call DrawSlot	;@04CD
	js DrawView_Right1	;@04D0
	mov al, 16h	;@04D2
	call DrawSlot	;@04D4
DrawView_Right1:	mov al, 8	;@04D7
	call DrawSlot	;@04D9
	js DrawView_Ahead2	;@04DC
	mov al, 0Dh	;@04DE
	call DrawSlot	;@04E0
	js DrawView_Ahead2	;@04E3
	mov al, 13h	;@04E5
	call DrawSlot	;@04E7
	js DrawView_Ahead2	;@04EA
	mov al, 1Ah	;@04EC
	call DrawSlot	;@04EE
; two cells ahead, the same
DrawView_Ahead2:	mov al, 0Ch	;@04F1
	call DrawSlot	;@04F3
	jne DrawView_Done	;@04F6
	mov al, 11h	;@04F8
	call DrawSlot	;@04FA
	js DrawView_Right2	;@04FD
	mov al, 17h	;@04FF
	call DrawSlot	;@0501
	js DrawView_Right2	;@0504
	mov al, 1Ch	;@0506
	call DrawSlot	;@0508
DrawView_Right2:	mov al, 12h	;@050B
	call DrawSlot	;@050D
	js DrawView_Ahead3	;@0510
	mov al, 19h	;@0512
	call DrawSlot	;@0514
	js DrawView_Ahead3	;@0517
	mov al, 1Fh	;@0519
	call DrawSlot	;@051B
; three cells ahead (the farthest): if open, only the walls beside it
DrawView_Ahead3:	mov al, 18h	;@051E
	call DrawSlot	;@0520
	js DrawView_Done	;@0523
	mov al, 1Dh	;@0525
	call DrawSlot	;@0527
	mov al, 1Eh	;@052A
	call DrawSlot	;@052C
DrawView_Done:	pop es	;@052F
	pop ax	;@0530
	popf	;@0531
	ret	;@0532
;------------------------------------------------------------------------------
; DrawSlot: draw what is in view slot AL: find its cell (the slot's offset turned to the facing,
; added to the position, wrapping at 16), read it, and draw its wall face and door, or in an open
; cell its ladders and chest.
; In: AL = slot 0-31. Out: ZF set (AL 0) = open cell; SF set (AL FF) = a wall or door, the line
; of sight ends; neither (AL 1) = slot 0 is a door (you stand in a doorway). Saves the rest.
;------------------------------------------------------------------------------
DrawSlot:	push ax	;@0533
	push bx	;@0534
	push dx	;@0535
	mov bl, al	;@0536
	mov bh, 0	;@0538
	mov dl, byte ptr SlotDXTbl[bx]	;@053A
	mov dh, byte ptr SlotDYTbl[bx]	;@053E
	mov ah, byte ptr ViewFacing	;@0542
	cmp ah, 0	;@0546
	je DrawSlot_Cell	;@0549
DrawSlot_Turn:	xchg dl, dh	; turn a quarter right: (dx,dy) -> (-dy,dx)	;@054B
	neg dl	;@054D
	dec ah	;@054F
	jne DrawSlot_Turn	;@0551
DrawSlot_Cell:	mov ah, al	; AH = slot	;@0553
	mov bx, word ptr ViewPos	;@0555
	add bl, dl	;@0559
	add bh, dh	;@055B
	and bx, 0F0Fh	; the map wraps around	;@055D
	call GetCell	;@0561
	test al, 0FFh	;@0564
	js DrawSlot_Wall	; 80-FF	;@0566
	mov dl, al	;@0568
	test dl, 10h	; ladder up?	;@056A
	je DrawSlot_TryDown	;@056D
	mov al, 0	;@056F
	call DrawLadder	;@0571
DrawSlot_TryDown:	test dl, 20h	; ladder down?	;@0574
	je DrawSlot_TryChest	;@0577
	mov al, 1	;@0579
	call DrawLadder	;@057B
DrawSlot_TryChest:	test dl, 40h	; chest?	;@057E
	je DrawSlot_Open	;@0581
	call DrawChest	;@0583
DrawSlot_Open:	mov al, 0	;@0586
	or al, al	;@0588
	jmp short DrawSlot_Ret	;@058A
DrawSlot_Wall:	cmp al, 0C0h	;@058C
	jae DrawSlot_Door	; C0-FF: door	;@058E
	call DrawFace	; 80-BF (wall, secret door A0): the plain wall	;@0590
	mov al, 0FFh	;@0593
	or al, al	;@0595
	jmp short DrawSlot_Ret	;@0597
DrawSlot_Door:	call DrawFace	; the wall...	;@0599
	add ah, 20h	;@059C
	call DrawFace	; ...and the door in it (slot 0: the opening is erased)	;@059F
	cmp ah, 20h	;@05A2
	je DrawSlot_InDoor	;@05A5
	mov al, 0FFh	;@05A7
	or al, al	;@05A9
	jmp short DrawSlot_Ret	;@05AB
DrawSlot_InDoor:	mov al, 1	;@05AD
	or al, al	;@05AF
DrawSlot_Ret:	pop dx	;@05B1
	pop bx	;@05B2
	pop ax	;@05B3
	ret	;@05B4
;------------------------------------------------------------------------------
; DrawFace: draw FaceTbl entry AH (a wall face 0-31 or a door 32-63) as vertical lines two pixels
; apart, moving the top and bottom by the entry's slopes (twice per line, once per pixel). When
; facing east or west every line is one pixel to the right, so the stripes change when you turn.
; Entry 32 (AH = 20h) erases instead (DrawVLine).
; In: AH = entry. Saves all.
;------------------------------------------------------------------------------
DrawFace:	push ax	;@05B5
	push bx	;@05B6
	push cx	;@05B7
	push dx	;@05B8
	push bp	;@05B9
	push si	;@05BA
	push di	;@05BB
	mov bl, ah	;@05BC
	mov bh, 0	;@05BE
	shl bx, 1	;@05C0
	shl bx, 1	;@05C2
	shl bx, 1	;@05C4
	mov di, bx	;@05C6
	lea di, FaceTbl[di]	;@05C8
	mov cl, byte ptr [di]	; x	;@05CC
	mov ch, byte ptr [di+1]	; top y	;@05CE
	mov dl, byte ptr [di+2]	; bottom y	;@05D1
	mov al, byte ptr [di+3]	; x step	;@05D4
	mov bl, byte ptr [di+4]	;@05D7
	mov bh, bl	;@05DA
	mov si, bx	; SI = top slope: BL reload, BH countdown	;@05DC
	mov bl, byte ptr [di+5]	;@05DE
	mov bh, bl	;@05E1
	mov bp, bx	; BP = bottom slope, the same	;@05E3
	mov bl, byte ptr [di+6]	;@05E5
	mov bh, 0	;@05E8
	mov di, bx	; DI = lines	;@05EA
	test byte ptr ViewFacing, 1	; east or west?	;@05EC
	je DrawFace_Loop	;@05F1
	inc cl	;@05F3
DrawFace_Loop:	call DrawVLine	;@05F5
	dec di	;@05F8
	je DrawFace_Done	;@05F9
	add cl, al	;@05FB
	mov bx, si	; first pixel: top, bottom	;@05FD
	dec bh	;@05FF
	jne DrawFace_Bot1	;@0601
	mov bh, bl	;@0603
	inc ch	;@0605
DrawFace_Bot1:	mov si, bx	;@0607
	mov bx, bp	;@0609
	dec bh	;@060B
	jne DrawFace_Half2	;@060D
	mov bh, bl	;@060F
	dec dl	;@0611
DrawFace_Half2:	mov bp, bx	;@0613
	cmp al, 1	; a step of 1 pixel: done (no entry has one)	;@0615
	je DrawFace_Loop	;@0617
	mov bx, si	; second pixel: top, bottom again	;@0619
	dec bh	;@061B
	jne DrawFace_Bot2	;@061D
	mov bh, bl	;@061F
	inc ch	;@0621
DrawFace_Bot2:	mov si, bx	;@0623
	mov bx, bp	;@0625
	dec bh	;@0627
	jne DrawFace_Next	;@0629
	mov bh, bl	;@062B
	dec dl	;@062D
DrawFace_Next:	mov bp, bx	;@062F
	jmp DrawFace_Loop	;@0631
DrawFace_Done:	pop di	;@0633
	pop si	;@0634
	pop bp	;@0635
	pop dx	;@0636
	pop cx	;@0637
	pop bx	;@0638
	pop ax	;@0639
	ret	;@063A
;------------------------------------------------------------------------------
; DrawLadder: draw a ladder in the open cell of slot AH (LadderTbl): two rails from the ceiling
; (up) or the floor (down) to the horizon, and two rungs. Nothing for slots 21-31 (too far).
; In: AH = slot, AL = 0 ladder up, 1 ladder down. Saves all.
;------------------------------------------------------------------------------
DrawLadder:	push ax	;@063B
	push cx	;@063C
	push dx	;@063D
	push si	;@063E
	cmp ah, 15h	;@063F
	jb DrawLadder_Go	;@0642
	jmp DrawLadder_Done	;@0644
DrawLadder_Go:	mov cl, ah	;@0647
	mov ch, 0	;@0649
	shl cx, 1	;@064B
	shl cx, 1	;@064D
	shl cx, 1	;@064F
	mov si, cx	;@0651
	lea si, LadderTbl[si]	;@0653
	mov cl, byte ptr [si]	; left rail x	;@0657
	mov dl, cl	;@0659
	test cl, 0FFh	;@065B
	js DrawLadder_Done	; x >= 80h: no ladder (no entry has one)	;@065E
	mov ch, byte ptr [si+2]	;@0660
	cmp ch, 0	;@0663
	je DrawLadder_Right	; left rail hidden	;@0666
	cmp al, 0	;@0668
	je DrawLadder_LRail	;@066A
	mov ch, 7Fh	; down: mirror to the floor	;@066C
	sub ch, byte ptr [si+2]	;@066E
DrawLadder_LRail:	mov ah, ch	;@0671
	mov dh, 40h	; to the horizon	;@0673
	call DrawLine	;@0675
	inc cl	; and again one pixel to the right	;@0678
	inc dl	;@067A
	mov ch, ah	;@067C
	call DrawLine	;@067E
DrawLadder_Right:	mov cl, byte ptr [si+1]	; right rail x	;@0681
	mov dl, cl	;@0684
	mov ch, byte ptr [si+3]	;@0686
	cmp ch, 0	;@0689
	je DrawLadder_Rungs	; right rail hidden	;@068C
	cmp al, 0	;@068E
	je DrawLadder_RRail	;@0690
	mov ch, 7Fh	;@0692
	sub ch, byte ptr [si+3]	;@0694
DrawLadder_RRail:	mov ah, ch	;@0697
	mov dh, 40h	;@0699
	call DrawLine	;@069B
	dec cl	;@069E
	dec dl	;@06A0
	mov ch, ah	;@06A2
	call DrawLine	;@06A4
DrawLadder_Rungs:	mov cl, byte ptr [si]	; rungs: from the left rail...	;@06A7
	mov dl, byte ptr [si+1]	; ...to the right rail	;@06A9
	mov ch, byte ptr [si+4]	;@06AC
	cmp al, 0	;@06AF
	je DrawLadder_Rung1	;@06B1
	mov ch, 7Fh	;@06B3
	sub ch, byte ptr [si+4]	;@06B5
DrawLadder_Rung1:	mov dh, ch	;@06B8
	call DrawLine	;@06BA
	mov cl, byte ptr [si]	;@06BD
	mov ch, byte ptr [si+5]	;@06BF
	cmp al, 0	;@06C2
	je DrawLadder_Rung2	;@06C4
	mov ch, 7Fh	;@06C6
	sub ch, byte ptr [si+5]	;@06C8
DrawLadder_Rung2:	mov dh, ch	;@06CB
	call DrawLine	;@06CD
DrawLadder_Done:	pop si	;@06D0
	pop dx	;@06D1
	pop cx	;@06D2
	pop ax	;@06D3
	ret	;@06D4
;------------------------------------------------------------------------------
; DrawLine: a straight line from (CL,CH) to (DL,DH) in view coordinates (Bresenham). The first
; point is not plotted, the last is; equal points would loop 65536 times (never asked).
; In: CL, CH = from x, y; DL, DH = to x, y. Saves all.
;------------------------------------------------------------------------------
DrawLine:	push ax	;@06D5
	push bx	;@06D6
	push cx	;@06D7
	push bp	;@06D8
	push si	;@06D9
	push di	;@06DA
	mov bl, dl	;@06DB
	sub bl, cl	;@06DD
	jae DrawLine_Right	;@06DF
	neg bl	;@06E1
	mov bp, bx	;@06E3
	mov bl, 0FFh	;@06E5
	jmp short DrawLine_DY	;@06E7
DrawLine_Right:	mov bp, bx	;@06E9
	mov bl, 1	;@06EB
DrawLine_DY:	xchg bp, bx	;@06ED
	mov bh, dh	;@06EF
	sub bh, ch	;@06F1
	jae DrawLine_Down	;@06F3
	neg bh	;@06F5
	xchg bp, bx	;@06F7
	mov bh, 0FFh	;@06F9
	jmp short DrawLine_Pick	;@06FB
DrawLine_Down:	xchg bp, bx	;@06FD
	mov bh, 1	;@06FF
DrawLine_Pick:	mov si, bx	; SI = x step (BL), y step (BH), +1 or -1	;@0701
	mov bx, bp	; BP = |dx| (BL), |dy| (BH)	;@0703
	cmp bl, bh	;@0705
	jb DrawLine_Steep	;@0707
	mov bh, 0	;@0709
	mov di, bx	; |dx| points, one per x	;@070B
	shr bl, 1	;@070D
	mov ah, bl	; AH = error, starts at |dx|/2	;@070F
DrawLine_XLoop:	mov bx, bp	;@0711
	add ah, bh	;@0713
	mov al, ah	;@0715
	sub al, bl	;@0717
	jb DrawLine_XStep	;@0719
	mov ah, al	;@071B
	mov bx, si	;@071D
	add ch, bh	;@071F
DrawLine_XStep:	mov bx, si	;@0721
	add cl, bl	;@0723
	call PlotPixel	;@0725
	dec di	;@0728
	jne DrawLine_XLoop	;@0729
	jmp short DrawLine_Done	;@072B
DrawLine_Steep:	mov bl, bh	;@072D
	mov bh, 0	;@072F
	mov di, bx	; |dy| points, one per y	;@0731
	shr bl, 1	;@0733
	mov ah, bl	;@0735
DrawLine_YLoop:	mov bx, bp	;@0737
	add ah, bl	;@0739
	mov al, ah	;@073B
	sub al, bh	;@073D
	jb DrawLine_YStep	;@073F
	mov ah, al	;@0741
	mov bx, si	;@0743
	add cl, bl	;@0745
DrawLine_YStep:	mov bx, si	;@0747
	add ch, bh	;@0749
	call PlotPixel	;@074B
	dec di	;@074E
	jne DrawLine_YLoop	;@074F
DrawLine_Done:	pop di	;@0751
	pop si	;@0752
	pop bp	;@0753
	pop cx	;@0754
	pop bx	;@0755
	pop ax	;@0756
	ret	;@0757
;------------------------------------------------------------------------------
; DrawChest: draw the chest in the open cell of slot AH as a filled box on the floor (ChestTbl).
; Nothing for slots 21-31. In: AH = slot. Saves all.
;------------------------------------------------------------------------------
DrawChest:	push bx	;@0758
	push cx	;@0759
	push dx	;@075A
	cmp ah, 15h	;@075B
	jae DrawChest_Done	;@075E
	mov bl, ah	;@0760
	mov bh, 0	;@0762
	shl bl, 1	;@0764
	shl bl, 1	;@0766
	lea bx, ChestTbl[bx]	;@0768
	mov cl, byte ptr [bx]	; left x	;@076C
	cmp cl, 0	;@076E
	js DrawChest_Done	; x >= 80h: none (no entry has one)	;@0771
	mov dh, byte ptr [bx+1]	; right x	;@0773
	mov ch, byte ptr [bx+2]	; top y	;@0776
	mov dl, byte ptr [bx+3]	; bottom y	;@0779
DrawChest_Loop:	call DrawVLine	;@077C
	inc cl	;@077F
	cmp cl, dh	;@0781
	jb DrawChest_Loop	;@0783
DrawChest_Done:	pop dx	;@0785
	pop cx	;@0786
	pop bx	;@0787
	ret	;@0788
;------------------------------------------------------------------------------
; DrawVLine: a vertical line at view x CL from y CH down to DL (excluded), white; or, when AH =
; 20h (the door around you, FaceTbl 32), black (erased). Screen pixel = view + 20h, the screen
; line's offset from ROWTAB. DL = CH would draw 65536 lines (never asked).
; In: CL = x, CH = top y, DL = bottom y, AH. Saves all.
;------------------------------------------------------------------------------
DrawVLine:	push ax	;@0789
	push bx	;@078A
	push cx	;@078B
	push dx	;@078C
	push si	;@078D
	push di	;@078E
	cmp ah, 20h	;@078F
	je DrawVLine_Erase	;@0792
	add cl, 20h	; screen x	;@0794
	sub dl, ch	;@0797
	mov dh, 0	; DX = lines	;@0799
	mov bl, cl	;@079B
	mov bh, 0	;@079D
	shr bx, 1	;@079F
	shr bx, 1	;@07A1
	mov di, bx	; DI = byte in the line (4 pixels a byte)	;@07A3
	mov al, 0C0h	; pixel value 3 (white)...	;@07A5
	and cl, 3	;@07A7
	shl cl, 1	;@07AA
	shr al, cl	; ...moved to the pixel's two bits	;@07AC
	mov bl, ch	;@07AE
	mov bh, 0	;@07B0
	shl bx, 1	;@07B2
	add bx, 40h	; screen line = y + 20h	;@07B4
	mov si, bx	;@07B7
	lea si, ROWTAB[si]	;@07B9
DrawVLine_Set:	mov bx, word ptr [si]	;@07BD
	add si, 2	;@07BF
	or byte ptr es:[bx+di], al	;@07C2
	dec dx	;@07C5
	jne DrawVLine_Set	;@07C6
	jmp short DrawVLine_Done	;@07C8
DrawVLine_Erase:	add cl, 20h	;@07CA
	sub dl, ch	;@07CD
	mov dh, 0	;@07CF
	mov bl, cl	;@07D1
	mov bh, 0	;@07D3
	shr bx, 1	;@07D5
	shr bx, 1	;@07D7
	mov di, bx	;@07D9
	mov al, 3Fh	; mask clearing the pixel's two bits	;@07DB
	and cl, 3	;@07DD
	shl cl, 1	;@07E0
	ror al, cl	;@07E2
	mov bl, ch	;@07E4
	mov bh, 0	;@07E6
	shl bx, 1	;@07E8
	add bx, 40h	;@07EA
	mov si, bx	;@07ED
	lea si, ROWTAB[si]	;@07EF
DrawVLine_Clear:	mov bx, word ptr [si]	;@07F3
	add si, 2	;@07F5
	and byte ptr es:[bx+di], al	;@07F8
	dec dx	;@07FB
	jne DrawVLine_Clear	;@07FC
DrawVLine_Done:	pop di	;@07FE
	pop si	;@07FF
	pop dx	;@0800
	pop cx	;@0801
	pop bx	;@0802
	pop ax	;@0803
	ret	;@0804
;------------------------------------------------------------------------------
; PlotPixel: set the pixel at view x CL, y CH to white (screen pixel = view + 20h).
; In: CL, CH. Saves all.
;------------------------------------------------------------------------------
PlotPixel:	push ax	;@0805
	push bx	;@0806
	push cx	;@0807
	add ch, 20h	; screen line	;@0808
	add cl, 20h	; screen x	;@080B
	mov al, cl	;@080E
	shr al, 1	;@0810
	shr al, 1	;@0812
	mov ah, 0C0h	;@0814
	and cl, 3	;@0816
	shl cl, 1	;@0819
	shr ah, cl	;@081B
	mov bl, ch	;@081D
	mov bh, 0	;@081F
	shl bx, 1	;@0821
	mov bx, word ptr ROWTAB[bx]	;@0823
	add bl, al	;@0827
	adc bh, 0	;@0829
	or byte ptr es:[bx], ah	;@082C
	pop cx	;@082F
	pop bx	;@0830
	pop ax	;@0831
	ret	;@0832
;------------------------------------------------------------------------------
; GetCell: read the dungeon cell (x, y) of the current level: DMAP + level*256 + y*16 + x
; (the same as EXODUS's DungeonCell). In: BL = x, BH = y (0-15). Out: AL = cell, BX = its address.
;------------------------------------------------------------------------------
GetCell:	pushf	;@0833
	shl bh, 1	;@0834
	shl bh, 1	;@0836
	shl bh, 1	;@0838
	shl bh, 1	;@083A
	add bl, bh	; y*16 + x	;@083C
	mov bh, byte ptr ViewLevel	; + level*256	;@083E
	lea bx, DMAP[bx]	;@0842
	mov al, byte ptr [bx]	;@0846
	popf	;@0848
	ret	;@0849
CODE ENDS
END
